17	func parseUsernameFromName(name string) (string, error) {
18		tokens, err := GetNameParentTokens(name, UserNamePrefix)
19		if err != nil {
20			return "", err
21		}
22		username := tokens[0]
23		if username == "" {
24			return "", errors.Errorf("invalid user name %q", name)
25		}
26		return username, nil
27	}
28	
29	func validateWritableUsername(username string) error {
30		if username == "" || isNumericUsername(username) || !base.UIDMatcher.MatchString(username) {
31			return errors.Errorf("invalid username %q", username)
32		}
33		return nil
34	}
35	
36	func isNumericUsername(username string) bool {
37		if username == "" {
38			return false
39		}
40		for _, char := range username {
41			if char < '0' || char > '9' {
42				return false
43			}
44		}
45		return true
46	}
47	
48	// ResolveUserByName resolves a username-based user resource name to a store user.
49	func ResolveUserByName(ctx context.Context, stores *store.Store, name string) (*store.User, error) {
50		username, err := parseUsernameFromName(name)
51		if err != nil {
52			return nil, err
53		}
54		user, err := stores.GetUser(ctx, &store.FindUser{Username: &username})
55		if err != nil {
56			return nil, errors.Wrap(err, "resolve user by name: GetUser failed")
57		}
